#!/usr/bin/env python3
# SCRAP V5
import zlib, hashlib

_A="ABCDEFGHJKLMNPQRSTUVWXYZ"
_P="""8729:"""
_H="da22d527c69d3ede300788fcc426096cc7c57625d16ccdfbee40a2df1e96c1b7"

def _d(s):
    ln, enc = s.split(":", 1)
    if not enc:
        data=b""
    else:
        pos={c:i for i,c in enumerate(_A)}
        n=0
        for c in enc:
            n=n*24+pos[c]
        size=(n.bit_length()+7)//8
        data=n.to_bytes(size, "big") if size else b""
    raw=zlib.decompress(data)
    return raw

try:
    _src=_d(_P)
    if hashlib.sha256(_src).hexdigest() != _H:
        raise RuntimeError("Integrity check failed")
    exec(compile(_src, __file__, "exec"), globals(), globals())
except Exception as e:
    print(f"\n[ERROR] {e}")
    raise
